thm:342C.statement_latex:
\begin{theorem}
\begin{gather}
G(2s) \Rightarrow B(2s), \label{eq:342j} \\
G(2s) \Rightarrow E(s, s), \label{eq:342k} \\
B(2s) \land C(s) \land D(s) \Rightarrow G(2s), \label{eq:342l} \\
B(2s) \land C(s) \Rightarrow E(s, s), \label{eq:342m} \\
