    \item $N(z)$: numerator polynomial of $R(z)$
    \item $D(z)$: denominator polynomial of $R(z)$
    \item $E(y)$: $E$-polynomial defined by $E(y)=D(iy)D(-iy)-N(iy)N(-iy)$
\end{itemize}

